50:   uint16_t format;      /* MS PCM = 1 */
51:   uint16_t channels;    /* channels, mono = 1, stereo = 2 */
52:   uint32_t sample_rate; /* samples per second = 44100 */
53:   uint32_t byte_rate;   /* bytes per second = samp_rate * byte_samp = 176400 */
54:   uint16_t frame_size;  /* block align (bytes per sample) = channels *
55:                            bits_per_sample / 8 = 4 */
