121:  */
122: unsigned char wave_open(const char *fname, wave_t *wave, shine_config_t *config,
123:                         int quiet) {
124:   static char *channel_mappings[] = {NULL, "mono", "stereo"};
125:   wave_chunk_t wave_chunk;
126:   fmt_chunk_t fmt_chunk;
127:   riff_chunk_header_t data_chunk;
128:   uint32_t fmt_data, fmt_length;
129: 
130:   if (!strcmp(fname, "-")) {
131:     /* TODO: support raw PCM stream with commandline parameters specifying
132:      * format */
133:     wave->file = stdin;
134:     wave->has_seek = 0;
135:   } else {
136:     wave->file = fopen(fname, "rb");
137:     wave->has_seek = 1;
138:   }
139: 
140:   if (!wave->file)
141:     error("Unable to open file");
142: 
143:   if (fread(&wave_chunk, sizeof(wave_chunk), 1, wave->file) != 1)
144:     error("Invalid header");
145: 
146:   if (strncmp(wave_chunk.header.id, "RIFF", 4) != 0)
147:     error("Not a MS-RIFF file");
148: 
149:   if (strncmp(wave_chunk.wave, "WAVE", 4) != 0)
150:     error("Not a WAVE audio file");
151: 
152:   /* Check the fmt chunk */
153:   if (!wave_get_chunk_header(wave->file, wave->has_seek, "fmt ",
154:                              (riff_chunk_header_t *)&fmt_chunk))
155:     error("WAVE fmt chunk not found");
156: 
157:   fmt_data = sizeof(fmt_chunk_t) - sizeof(riff_chunk_header_t);
158: 
159:   if (fread(&fmt_chunk.format, fmt_data, 1, wave->file) != 1)
160:     error("Read error");
161: 
162: #ifdef SHINE_BIG_ENDIAN
163:   native_fmt_chunk(fmt_chunk);
164: #endif
165: 
166:   if (verbose())
167:     fprintf(stderr, "WAVE format: %u\n", fmt_chunk.format);
168: 
169:   if (fmt_chunk.format != 1)
170:     error("Unknown WAVE format");
171: 
172:   if (fmt_chunk.channels > 2)
173:     error("More than 2 channels");
174: 
175:   if (fmt_chunk.depth != 16)
176:     error("Unsupported PCM bit depth");
177: 
178:   // Skip remaining data.
179:   fmt_length = fmt_chunk.header.length + fmt_chunk.header.length % 2;
180:   if (fmt_length > fmt_data)
181:     wave_seek(wave->file, wave->has_seek, fmt_length - fmt_data);
182: 
183:   /* Position the file pointer at the data chunk */
184:   if (!wave_get_chunk_header(wave->file, wave->has_seek, "data", &data_chunk))
185:     error("WAVE data chunk not found");
186: 
187:   config->wave.channels = fmt_chunk.channels;
188:   config->wave.samplerate = fmt_chunk.sample_rate;
189: 
190:   wave->channels = fmt_chunk.channels;
191:   wave->length = data_chunk.length;
192:   wave->duration = data_chunk.length / fmt_chunk.byte_rate;
193: 
194:   if (!quiet)
195:     printf("%s, %s %ldHz %ldbit, duration: %02ld:%02ld:%02ld\n",
196:            "WAVE PCM Data", channel_mappings[fmt_chunk.channels],
197:            (long)fmt_chunk.sample_rate, (long)fmt_chunk.depth,
198:            (long)wave->duration / 3600, (long)(wave->duration / 60) % 60,
199:            (long)wave->duration % 60);
200:   return 1;
