252:   if (samples_read < frame_size &&
253:       samples_read > 0) { /* Pad sample with zero's */
254:     memset(sample_buffer + samples_read, 0,
255:            (frame_size - samples_read) * sizeof(int16_t));
256:     samples_read = frame_size;
